begin;
create schema if not exists crm_private;
revoke all on schema crm_private from public;
grant usage on schema crm_private to authenticated,anon;
create table public.developers(id bigint generated always as identity primary key,name text not null check(length(name) between 2 and 160),website text,contact_name text,phone text,email text,disclosure_rules text,created_at timestamptz not null default now());
create table public.developments(id bigint generated always as identity primary key,developer_id bigint references public.developers(id),name text not null check(length(name) between 2 and 160),location text,description text,typologies text,sales_conditions text,status text not null default 'planejamento' check(status in ('planejamento','lancamento','em obras','entregue')),delivery_date date,created_at timestamptz not null default now());
create table public.development_units(id bigint generated always as identity primary key,development_id bigint not null references public.developments(id),property_id bigint not null unique references public.properties(id),unit_label text not null,created_at timestamptz not null default now());
create table public.marketing_assets(id bigint generated always as identity primary key,owner_id uuid not null default auth.uid() references auth.users(id),scope text not null default 'personal' check(scope in ('personal','institutional')),title text not null check(length(title) between 2 and 160),category text not null default 'foto' check(category in ('foto','render','planta','video','tour','pdf','folder','tabela','story','feed','anuncio','documento')),tags text[] not null default '{}',description text,source_url text,status text not null default 'pendente' check(status in ('pendente','aprovado','arquivado')),visibility text not null default 'internal' check(visibility in ('internal','public')),expires_at timestamptz,current_version_id bigint,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.asset_versions(id bigint generated always as identity primary key,asset_id bigint not null references public.marketing_assets(id),storage_path text not null unique check(storage_path ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}\.(webp|jpg|jpeg|png|pdf|mp4)$'),mime_type text not null check(mime_type in ('image/webp','image/jpeg','image/png','application/pdf','video/mp4')),size_bytes bigint not null check(size_bytes>0 and size_bytes<=52428800),checksum text not null check(checksum ~ '^[0-9a-f]{64}$'),original_name text not null check(length(original_name)<=255),created_at timestamptz not null default now(),unique(asset_id,checksum));
alter table public.marketing_assets add constraint marketing_current_version_fk foreign key(current_version_id) references public.asset_versions(id);
create table public.asset_relations(id bigint generated always as identity primary key,asset_id bigint not null references public.marketing_assets(id),property_id bigint references public.properties(id),development_id bigint references public.developments(id),created_at timestamptz not null default now(),check(num_nonnulls(property_id,development_id)=1),unique(asset_id,property_id),unique(asset_id,development_id));
create table public.marketing_collections(id bigint generated always as identity primary key,owner_id uuid not null default auth.uid() references auth.users(id),name text not null check(length(name) between 2 and 160),description text,created_at timestamptz not null default now());
create table public.marketing_collection_items(id bigint generated always as identity primary key,collection_id bigint not null references public.marketing_collections(id) on delete cascade,property_id bigint references public.properties(id),asset_id bigint references public.marketing_assets(id),created_at timestamptz not null default now(),check(num_nonnulls(property_id,asset_id)=1),unique(collection_id,property_id),unique(collection_id,asset_id));
create table public.marketing_favorites(owner_id uuid not null default auth.uid() references auth.users(id),asset_id bigint not null references public.marketing_assets(id),created_at timestamptz not null default now(),primary key(owner_id,asset_id));
create table public.marketing_shares(id bigint generated always as identity primary key,token uuid not null default gen_random_uuid() unique,owner_id uuid not null default auth.uid() references auth.users(id),lead_id bigint references public.leads(id),client_id bigint references public.clients(id),collection_id bigint references public.marketing_collections(id),property_ids bigint[] not null check(cardinality(property_ids) between 1 and 12),asset_ids bigint[] not null default '{}' check(cardinality(asset_ids)<=60),title text not null check(length(title) between 2 and 160),message text check(length(message)<=2000),channel text not null default 'copy' check(channel in ('copy','whatsapp','direct')),expires_at timestamptz not null default(now()+interval '7 days'),revoked_at timestamptz,created_at timestamptz not null default now());
create table public.marketing_share_events(id bigint generated always as identity primary key,share_id bigint not null references public.marketing_shares(id),nonce uuid not null,event_type text not null default 'consented_open' check(event_type='consented_open'),created_at timestamptz not null default now(),unique(share_id,nonce));
create table public.crm_automation_preferences(owner_id uuid primary key default auth.uid() references auth.users(id),share_followup boolean not null default false,followup_days integer not null default 2 check(followup_days between 1 and 30),updated_at timestamptz not null default now());
create table public.crm_event_log(id bigint generated always as identity primary key,owner_id uuid references auth.users(id),event_type text not null,entity_id bigint not null,idempotency_key text not null unique,status text not null default 'done',created_at timestamptz not null default now());
create table public.asset_imports(id bigint generated always as identity primary key,owner_id uuid not null default auth.uid() references auth.users(id),file_name text not null,status text not null check(status in ('uploaded','duplicate','failed')),asset_id bigint references public.marketing_assets(id),error_message text,created_at timestamptz not null default now());
-- Explicit access: no anonymous table exposure, opaque-token RPC is the public boundary.
do $$ declare t text; begin foreach t in array array['developers','developments','development_units','marketing_assets','asset_versions','asset_relations','marketing_collections','marketing_collection_items','marketing_favorites','marketing_shares','marketing_share_events','crm_automation_preferences','crm_event_log','asset_imports'] loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on public.%I from anon',t); execute format('grant select,insert,update,delete on public.%I to authenticated',t); end loop; end $$;
grant usage,select on all sequences in schema public to authenticated;
create policy developers_read on public.developers for select to authenticated using(public.can_manage_commercial());
create policy developers_write on public.developers for all to authenticated using(public.can_manage_operations()) with check(public.can_manage_operations());
create policy developments_read on public.developments for select to authenticated using(public.can_manage_commercial());
create policy developments_write on public.developments for all to authenticated using(public.can_manage_operations()) with check(public.can_manage_operations());
create policy units_read on public.development_units for select to authenticated using(public.can_manage_commercial() and exists(select 1 from public.properties p where p.id=property_id));
create policy units_write on public.development_units for all to authenticated using(public.can_manage_operations()) with check(public.can_manage_operations());
create policy assets_read on public.marketing_assets for select to authenticated using(public.can_manage_commercial() and(owner_id=auth.uid() or public.can_manage_operations() or(scope='institutional' and status='aprovado')));
create policy assets_insert on public.marketing_assets for insert to authenticated with check(public.can_manage_commercial() and owner_id=auth.uid() and(scope='personal' or public.can_manage_operations()));
create policy assets_update on public.marketing_assets for update to authenticated using(public.can_manage_commercial() and(owner_id=auth.uid() or public.can_manage_operations())) with check(public.can_manage_commercial() and(owner_id=auth.uid() or public.can_manage_operations()));
create policy versions_read on public.asset_versions for select to authenticated using(exists(select 1 from public.marketing_assets a where a.id=asset_id));
create policy versions_insert on public.asset_versions for insert to authenticated with check(public.can_manage_commercial() and split_part(storage_path,'/',1)=auth.uid()::text and exists(select 1 from public.marketing_assets a where a.id=asset_id and(a.owner_id=auth.uid() or public.can_manage_operations())));
create policy relations_read on public.asset_relations for select to authenticated using(exists(select 1 from public.marketing_assets a where a.id=asset_id));
create policy relations_write on public.asset_relations for all to authenticated using(exists(select 1 from public.marketing_assets a where a.id=asset_id and(a.owner_id=auth.uid() or public.can_manage_operations()))) with check(exists(select 1 from public.marketing_assets a where a.id=asset_id and(a.owner_id=auth.uid() or public.can_manage_operations())) and ((development_id is not null and public.can_manage_operations()) or exists(select 1 from public.properties p where p.id=property_id and(public.can_manage_operations() or p.owner_id=auth.uid() or p.broker_id=auth.uid()))));
create policy collections_owner on public.marketing_collections for all to authenticated using(public.can_manage_commercial() and owner_id=auth.uid()) with check(public.can_manage_commercial() and owner_id=auth.uid());
create policy collection_items_owner on public.marketing_collection_items for all to authenticated using(exists(select 1 from public.marketing_collections c where c.id=collection_id)) with check(exists(select 1 from public.marketing_collections c where c.id=collection_id) and ((asset_id is not null and exists(select 1 from public.marketing_assets a where a.id=asset_id)) or(property_id is not null and exists(select 1 from public.properties p where p.id=property_id))));
create policy favorites_owner on public.marketing_favorites for all to authenticated using(public.can_manage_commercial() and owner_id=auth.uid()) with check(public.can_manage_commercial() and owner_id=auth.uid() and exists(select 1 from public.marketing_assets a where a.id=asset_id));
create policy shares_read on public.marketing_shares for select to authenticated using(public.can_manage_commercial() and(owner_id=auth.uid() or public.can_manage_operations()));
create policy shares_insert on public.marketing_shares for insert to authenticated with check(public.can_manage_commercial() and owner_id=auth.uid());
create policy shares_update on public.marketing_shares for update to authenticated using(public.can_manage_commercial() and(owner_id=auth.uid() or public.can_manage_operations())) with check(public.can_manage_commercial() and(owner_id=auth.uid() or public.can_manage_operations()));
create policy share_events_read on public.marketing_share_events for select to authenticated using(exists(select 1 from public.marketing_shares s where s.id=share_id));
revoke insert,update,delete on public.marketing_share_events from authenticated;
create policy automation_owner on public.crm_automation_preferences for all to authenticated using(public.can_manage_commercial() and owner_id=auth.uid()) with check(public.can_manage_commercial() and owner_id=auth.uid());
create policy event_log_read on public.crm_event_log for select to authenticated using(public.can_manage_commercial() and(owner_id=auth.uid() or public.can_manage_operations()));
revoke insert,update,delete on public.crm_event_log from authenticated;
create policy imports_owner on public.asset_imports for all to authenticated using(public.can_manage_commercial() and owner_id=auth.uid()) with check(public.can_manage_commercial() and owner_id=auth.uid());
create function crm_private.guard_asset() returns trigger language plpgsql security invoker set search_path=public as $$ begin
if tg_op='UPDATE' then
 if new.owner_id<>old.owner_id or new.scope<>old.scope then raise exception using errcode='42501',message='Proprietário e escopo são permanentes.'; end if;
 if (new.status is distinct from old.status and new.status='aprovado') or(new.visibility is distinct from old.visibility and new.visibility='public') then if not public.can_manage_operations() then raise exception using errcode='42501',message='A gestão deve aprovar a divulgação.'; end if; end if;
 -- Changing the file of approved material always requires reapproval, including manager uploads.
 if new.current_version_id is distinct from old.current_version_id then new.status:='pendente'; end if;
else if (new.status='aprovado' or new.visibility='public') and not public.can_manage_operations() then raise exception using errcode='42501',message='A gestão deve aprovar a divulgação.'; end if;
end if;
if new.current_version_id is not null and not exists(select 1 from public.asset_versions v where v.id=new.current_version_id and v.asset_id=new.id) then raise exception using errcode='23514',message='Versão inválida.'; end if;
new.updated_at:=now();return new;end $$;
create trigger marketing_asset_guard before insert or update on public.marketing_assets for each row execute function crm_private.guard_asset();
-- Private helper supplies a narrow public capability, never lead/client records.
create function crm_private.valid_share(target_token uuid) returns bigint language sql stable security definer set search_path=public as $$
select s.id from public.marketing_shares s where s.token=target_token and s.revoked_at is null and s.expires_at>now() and not exists(select 1 from unnest(s.property_ids) pid where not exists(select 1 from public.properties p where p.id=pid and p.deleted_at is null and p.publish_on_site and p.presentation_enabled and p.workflow_status in ('aprovado','publicado') and p.status in ('ativo','reservado','vendido','alugado'))) $$;
revoke all on function crm_private.valid_share(uuid) from public,anon,authenticated;
create function crm_private.public_asset(path text) returns boolean language sql stable security definer set search_path=public as $$
select exists(select 1 from public.marketing_assets a join public.asset_versions v on v.id=a.current_version_id join public.asset_relations r on r.asset_id=a.id join public.properties p on p.id=r.property_id or exists(select 1 from public.development_units u where u.property_id=p.id and u.development_id=r.development_id) where v.storage_path=path and a.status='aprovado' and a.visibility='public' and(a.expires_at is null or a.expires_at>now()) and p.deleted_at is null and p.publish_on_site and p.presentation_enabled and p.workflow_status in ('aprovado','publicado') and p.status in ('ativo','reservado','vendido','alugado')) $$;
revoke all on function crm_private.public_asset(text) from public;
grant execute on function crm_private.public_asset(text) to anon,authenticated;
create function crm_private.guard_share() returns trigger language plpgsql security invoker set search_path=public as $$ declare pid bigint;aid bigint; begin
if tg_op='UPDATE' then if (to_jsonb(new)-'revoked_at')<>(to_jsonb(old)-'revoked_at') or old.revoked_at is not null or new.revoked_at is null then raise exception using errcode='42501',message='Links são imutáveis. Revogue e gere um novo link.';end if;return new;end if;
if new.expires_at<=now() or new.expires_at>now()+interval '90 days' then raise exception using errcode='23514',message='Validade deve ficar entre agora e 90 dias.';end if;
if new.lead_id is not null and not exists(select 1 from public.leads l where l.id=new.lead_id) then raise exception using errcode='42501',message='Lead não autorizado.';end if;
if new.client_id is not null and not exists(select 1 from public.clients c where c.id=new.client_id and c.deleted_at is null) then raise exception using errcode='42501',message='Cliente não autorizado.';end if;
if new.collection_id is not null and not exists(select 1 from public.marketing_collections c where c.id=new.collection_id) then raise exception using errcode='42501',message='Coleção não autorizada.';end if;
foreach pid in array new.property_ids loop if not exists(select 1 from public.properties p where p.id=pid and p.deleted_at is null and p.publish_on_site and p.presentation_enabled and p.workflow_status in ('aprovado','publicado') and p.status in ('ativo','reservado','vendido','alugado')) then raise exception using errcode='42501',message='Imóvel sem apresentação pública autorizada.';end if;end loop;
foreach aid in array new.asset_ids loop if not exists(select 1 from public.marketing_assets a join public.asset_versions v on v.id=a.current_version_id where a.id=aid and a.status='aprovado' and a.visibility='public' and(a.expires_at is null or a.expires_at>now()) and exists(select 1 from public.asset_relations r where r.asset_id=a.id and(r.property_id=any(new.property_ids) or exists(select 1 from public.development_units u where u.development_id=r.development_id and u.property_id=any(new.property_ids))))) then raise exception using errcode='42501',message='Material sem aprovação ou vínculo autorizado.';end if;end loop;
return new;end $$;
create trigger marketing_share_guard before insert or update on public.marketing_shares for each row execute function crm_private.guard_share();
create function crm_private.share_created() returns trigger language plpgsql security definer set search_path=public as $$ begin
if new.lead_id is not null then insert into public.lead_activities(lead_id,user_id,type,description) values(new.lead_id,new.owner_id,'note','Apresentação gerada: '||new.title||' · canal '||new.channel||' · link '||new.token::text); end if;
insert into public.crm_event_log(owner_id,event_type,entity_id,idempotency_key) values(new.owner_id,'presentation_created',new.id,'share:'||new.id);
if new.lead_id is not null and exists(select 1 from public.crm_automation_preferences where owner_id=new.owner_id and share_followup) then insert into public.tasks(title,broker_id,lead_id,property_id,due_at) select 'Retornar sobre apresentação: '||new.title,new.owner_id,new.lead_id,new.property_ids[1],now()+make_interval(days=>p.followup_days) from public.crm_automation_preferences p where p.owner_id=new.owner_id;end if;return new;end $$;
revoke all on function crm_private.share_created() from public,anon,authenticated;
create trigger marketing_share_created after insert on public.marketing_shares for each row execute function crm_private.share_created();
create function public.crm_public_presentation(target_token uuid) returns jsonb language sql stable security definer set search_path=public as $$
select jsonb_build_object('title',s.title,'message',s.message,'expires_at',s.expires_at,'broker',(select jsonb_build_object('name',b.name,'phone',b.phone,'creci',b.creci) from public.brokers b where b.id=s.owner_id and b.active),'properties',(select jsonb_agg(jsonb_build_object('id',p.id,'title',p.title,'property_code',p.property_code,'slug',p.slug,'description',p.description,'location',p.location,'price',p.price,'bedrooms',p.bedrooms,'bathrooms',p.bathrooms,'garage',p.garage,'area',p.area,'images',p.images,'videos',p.videos,'status',p.status)) from public.properties p where p.id=any(s.property_ids)),'assets',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'title',a.title,'category',a.category,'mime_type',v.mime_type,'size_bytes',v.size_bytes,'path',v.storage_path)) from public.marketing_assets a join public.asset_versions v on v.id=a.current_version_id where a.id=any(s.asset_ids) and crm_private.public_asset(v.storage_path)),'[]'::jsonb)) from public.marketing_shares s where s.id=crm_private.valid_share(target_token) $$;
revoke all on function public.crm_public_presentation(uuid) from public;
grant execute on function public.crm_public_presentation(uuid) to anon,authenticated;
create function public.crm_record_presentation_open(target_token uuid,event_nonce uuid,consented boolean) returns boolean language plpgsql security definer set search_path=public as $$ declare sid bigint;begin
if not coalesce(consented,false) then return false;end if;sid:=crm_private.valid_share(target_token);if sid is null then return false;end if;
if (select count(*) from public.marketing_share_events where share_id=sid)>10000 then return false;end if;
insert into public.marketing_share_events(share_id,nonce) values(sid,event_nonce) on conflict(share_id,nonce) do nothing;return true;end $$;
revoke all on function public.crm_record_presentation_open(uuid,uuid,boolean) from public;
grant execute on function public.crm_record_presentation_open(uuid,uuid,boolean) to anon,authenticated;
-- Private uploads only. Public reads require current approved/public version tied to an eligible property.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('crm-marketing','crm-marketing',false,52428800,array['image/webp','image/jpeg','image/png','application/pdf','video/mp4']);
create policy marketing_storage_upload on storage.objects for insert to authenticated with check(bucket_id='crm-marketing' and public.can_manage_commercial() and split_part(name,'/',1)=auth.uid()::text and name ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}\.(webp|jpg|jpeg|png|pdf|mp4)$');
create policy marketing_storage_read on storage.objects for select to authenticated using(bucket_id='crm-marketing' and(public.can_manage_commercial() and(split_part(name,'/',1)=auth.uid()::text or public.can_manage_operations() or exists(select 1 from public.asset_versions v join public.marketing_assets a on a.id=v.asset_id where v.storage_path=name))));
create policy marketing_storage_public on storage.objects for select to anon using(bucket_id='crm-marketing' and crm_private.public_asset(name));
create index asset_versions_asset_idx on public.asset_versions(asset_id);
create index asset_relations_property_idx on public.asset_relations(property_id);
create index asset_relations_development_idx on public.asset_relations(development_id);
create index marketing_assets_owner_idx on public.marketing_assets(owner_id);
create index marketing_assets_status_idx on public.marketing_assets(status,visibility);
create index marketing_shares_owner_idx on public.marketing_shares(owner_id,created_at);
create index marketing_shares_lead_idx on public.marketing_shares(lead_id);
create index marketing_share_events_share_idx on public.marketing_share_events(share_id);
create index developments_developer_idx on public.developments(developer_id);
create index development_units_development_idx on public.development_units(development_id);
create index collection_items_collection_idx on public.marketing_collection_items(collection_id);
create trigger marketing_assets_audit after insert or update on public.marketing_assets for each row execute function public.crm_audit_change();
create trigger marketing_shares_audit after insert or update on public.marketing_shares for each row execute function public.crm_audit_change();
do $$ declare t text;begin if exists(select 1 from pg_publication where pubname='supabase_realtime') then foreach t in array array['developers','developments','development_units','marketing_assets','asset_versions','asset_relations','marketing_collections','marketing_collection_items','marketing_shares','marketing_share_events','crm_automation_preferences','crm_event_log','asset_imports'] loop execute format('alter publication supabase_realtime add table public.%I',t);end loop;end if;end $$;
notify pgrst,'reload schema';
commit;

